const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Point(107.5, 52.0); // A point in Southern Siberia (near Lake Baikal)
  const scale = 1000; // Use a reasonable scale to avoid memory issues for reduceRegion

  // Period 1: October 14, 2018
  const start1 = '2018-10-14';
  const end1 = '2018-10-15'; // Single day

  // Period 2: October 29, 2018
  const start2 = '2018-10-29';
  const end2 = '2018-10-30'; // Single day

  // Function to mask non-snow pixels and calculate snow fraction
  const calculateSnowFraction = (image) => {
    // NDSI_Snow_Cover values: 1-100 are snow, 0 is no snow, others are fill, cloud, water.
    // We are interested in actual snow cover (1-100).
    const snowCover = image.select('NDSI_Snow_Cover');

    // Create a binary mask for snow: 1 for snow, 0 for non-snow/other
    const snowMask = snowCover.gt(0).and(snowCover.lte(100)).rename('snow_present');

    // Add this binary snow mask band to the image for later pixel counting
    return image.addBands(snowMask);
  };

  // Function to process a collection for a given period
  const processPeriod = async (start, end, periodName) => {
    const collection = ee.ImageCollection('MODIS/061/MOD10A1')
      .filterBounds(geometry)
      .filterDate(start, end);

    const collectionSize = await collection.size().getInfo();
    console.log(`${periodName} Images: ${collectionSize}`);

    if (collectionSize === 0) {
      return { snowFraction: null, validPixels: 0 };
    }

    // Since we're looking at a single day, we'll try to get the first available image.
    // If multiple images are there (e.g. from different orbits), a mosaic would be better.
    // For simplicity, take the first image if available, assuming daily product for a point.
    // A robust approach would be to mosaic. Let's mosaic to handle multiple images/orbits for a day.
    const image = collection.mosaic().map(calculateSnowFraction).first();
    if (image === null) {
      console.log(`No valid image for ${periodName} after processing.`);
      return { snowFraction: null, validPixels: 0 };
    }

    const snowImage = image.select('snow_present');

    // Calculate total valid pixels within the geometry (where NDSI_Snow_Cover is not fill/cloud/water)
    // Here, we count pixels where snow is either present or absent (NDSI_Snow_Cover == 0).
    const allValidPixels = image.select('NDSI_Snow_Cover').gt(-1).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    }).get('NDSI_Snow_Cover');

    // Calculate the number of snow-covered pixels
    const snowPixels = snowImage.reduceRegion({
      reducer: ee.Reducer.sum(), // Sum of 1s (snow_present)
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('snow_present');

    const totalValidPixels = await allValidPixels.getInfo();
    const numSnowPixels = await snowPixels.getInfo();

    if (totalValidPixels === 0) {
      console.log(`No valid observation pixels for ${periodName}.`);
      return { snowFraction: null, validPixels: 0 };
    }

    const fraction = (numSnowPixels / totalValidPixels) * 100;

    return { snowFraction: fraction, validPixels: totalValidPixels };
  };

  // Process Period 1
  const result1 = await processPeriod(start1, end1, 'Oct 14, 2018');
  const snowFraction1 = result1.snowFraction;
  const validPixels1 = result1.validPixels;

  if (snowFraction1 === null && validPixels1 === 0) {
    console.log("C1: No data or valid pixels for Oct 14, 2018.");
    console.log("C1");
    return;
  }
  if (validPixels1 === 0) {
    console.log("C2: No valid pixels remain for Oct 14, 2018 after processing.");
    console.log("C2");
    return;
  }
  if (snowFraction1 === null || isNaN(snowFraction1)) {
    console.log("C3: Calculation failure for Oct 14, 2018 snow fraction.");
    console.log("C3");
    return;
  }

  // Process Period 2
  const result2 = await processPeriod(start2, end2, 'Oct 29, 2018');
  const snowFraction2 = result2.snowFraction;
  const validPixels2 = result2.validPixels;

  if (snowFraction2 === null && validPixels2 === 0) {
    console.log("C1: No data or valid pixels for Oct 29, 2018.");
    console.log("C1");
    return;
  }
  if (validPixels2 === 0) {
    console.log("C2: No valid pixels remain for Oct 29, 2018 after processing.");
    console.log("C2");
    return;
  }
  if (snowFraction2 === null || isNaN(snowFraction2)) {
    console.log("C3: Calculation failure for Oct 29, 2018 snow fraction.");
    console.log("C3");
    return;
  }

  console.log(`Oct 14, 2018 Snow Cover: ${snowFraction1.toFixed(2)}% (Valid Pixels: ${validPixels1})`);
  console.log(`Oct 29, 2018 Snow Cover: ${snowFraction2.toFixed(2)}% (Valid Pixels: ${validPixels2})`);

  // Compare snow cover
  if (snowFraction2 > snowFraction1) {
    console.log("A"); // Yes, snow cover increased
  } else {
    console.log("B"); // No, snow cover did not increase
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
